int list_save(node *head, char *filename) {
    FILE *file;
    node *current = head;
    char line[MAX_LINE_LEN];

    if ((file = fopen(filename, "w")) == NULL) {
        return -1;
    }

    while (current!= NULL) {
        sprintf(line, "%s,%f,%d\n", current->item_name, current->price, current->quantity);
        if (fwrite(line, strlen(line), 1, file)!= 1) {
            fclose(file);
            return -1;
        }
        current = current->next;
    }

    fclose(file);
    return 0;
}
